import typing
import re

class TemplateError(Exception):
    """Base class for template errors."""
    pass

class TemplateSyntaxError(TemplateError):
    """Syntax error in the template."""
    def __init__(self, message: str, lineno: int):
        self.message = message
        self.lineno = lineno
        super().__init__(f"line {lineno}: {message}")

class TemplateRenderError(TemplateError):
    """Render error during execution."""
    def __init__(self, message: str, lineno: int):
        self.message = message
        self.lineno = lineno
        super().__init__(f"line {lineno}: {message}")

class Token(typing.NamedTuple):
    kind: str
    value: str
    lineno: int

def tokenize(source: str) -> list[Token]:
    """
    Tokenize the template source into a list of Tokens.
    """
    tokens: list[Token] = []

    pos = 0
    line = 1
    length = len(source)

    text_buffer = []
    text_start_line = 1

    def flush_text():
        nonlocal text_buffer, text_start_line
        if text_buffer:
            tokens.append(Token("text", "".join(text_buffer), text_start_line))
            text_buffer = []
            text_start_line = line # Reset start line for next text segment? 
            # Actually, text_start_line should be updated when we start accumulating new text.
            # We will handle this in the main loop.

    # Helper to find next tag start
    # Returns (index, type_char) or (-1, None)
    def find_tag_start(p):
        min_idx = -1
        min_char = None

        # Search for {{
        idx = source.find("{{", p)
        if idx != -1:
            min_idx = idx
            min_char = '{'

        # Search for {%
        idx = source.find("{%", p)
        if idx != -1:
            if min_idx == -1 or idx < min_idx:
                min_idx = idx
                min_char = '%'

        # Search for {#
        idx = source.find("{#", p)
        if idx != -1:
            if min_idx == -1 or idx < min_idx:
                min_idx = idx
                min_char = '#'

        return min_idx, min_char

    while pos < length:
        idx, tag_type = find_tag_start(pos)

        if idx == -1:
            # No more tags. Rest is text.
            chunk = source[pos:]
            if chunk:
                if not text_buffer:
                    text_start_line = line
                for char in chunk:
                    text_buffer.append(char)
                    if char == '\n':
                        line += 1
                pos = length
            break

        # Add text before tag to buffer
        chunk = source[pos:idx]
        if chunk:
            if not text_buffer:
                text_start_line = line
            for char in chunk:
                text_buffer.append(char)
                if char == '\n':
                    line += 1

        # Flush any pending text
        flush_text()

        # Determine closing delimiter and token kind
        if tag_type == '{':
            closing = "}}"
            token_kind = "var"
        elif tag_type == '%':
            closing = "%}"
            token_kind = "block"
        else: # '#'
            closing = "#}"
            token_kind = "comment"

        # Record line where tag starts
        tag_line = line

        # Move past opening delimiter
        pos = idx + 2

        # Find closing delimiter
        end_idx = source.find(closing, pos)

        if end_idx == -1:
            raise TemplateSyntaxError("Unclosed tag", tag_line)

        # Extract content
        content = source[pos:end_idx]

        # Update line count based on content newlines
        # We need to update 'line' for subsequent tokens
        # But the tag's own line is tag_line.
        # Newlines inside the tag affect the line number of the NEXT token.
        nl_count = content.count('\n')
        line += nl_count

        pos = end_idx + len(closing)

        if token_kind == "comment":
            # Comments produce no token.
            # However, we must reset text_start_line for the next text segment.
            # The next text segment starts at 'pos', which is on 'line'.
            pass
        else:
            val = content.strip()
            tokens.append(Token(token_kind, val, tag_line))

    flush_text()

    return tokens
