from .lexer import Token, TemplateSyntaxError, tokenize
import re

# AST Nodes
class Node:
    pass

class TextNode(Node):
    def __init__(self, text):
        self.text = text

class VarNode(Node):
    def __init__(self, expr, lineno):
        self.expr = expr
        self.lineno = lineno

class IfNode(Node):
    def __init__(self, branches, else_body, lineno):
        # branches: list of (condition, body)
        self.branches = branches
        self.else_body = else_body
        self.lineno = lineno

class ForNode(Node):
    def __init__(self, target, iter_expr, body, else_body, lineno):
        self.target = target
        self.iter_expr = iter_expr
        self.body = body
        self.else_body = else_body
        self.lineno = lineno

# Expression Nodes
class ExprNode:
    pass

class LiteralNode(ExprNode):
    def __init__(self, value):
        self.value = value

class VarPathNode(ExprNode):
    def __init__(self, root, segments):
        # root: str
        # segments: list of str (names or int strings)
        self.root = root
        self.segments = segments

class FilterNode(ExprNode):
    def __init__(self, target, name, args):
        # target: ExprNode
        # name: str
        # args: list of LiteralNode (arguments to filter)
        self.target = target
        self.name = name
        self.args = args

class ConditionNode(ExprNode):
    # For if/elif conditions
    # type: 'and', 'or', 'not', 'comp', 'val'
    def __init__(self, type, *args):
        self.type = type
        self.args = args

def _tokenize_inner(source_text: str, lineno: int):
    """
    Tokenize the inside of a tag into simple tokens for expression/condition parsing.
    Returns list of tokens (strings).
    """
    tokens = []
    i = 0
    n = len(source_text)
    while i < n:
        c = source_text[i]
        if c.isspace():
            i += 1
            continue

        # Two char operators
        if i < n - 1:
            two = source_text[i:i+2]
            if two in ("==", "!=", "<=", ">="):
                tokens.append(two)
                i += 2
                continue

        # One char operators
        if c in "<>":
            tokens.append(c)
            i += 1
            continue

        if c in "|.:":
            tokens.append(c)
            i += 1
            continue

        # String
        if c in "\"'":
            quote = c
            j = i + 1
            found_end = False
            while j < n:
                if source_text[j] == quote:
                    found_end = True
                    break
                j += 1
            if not found_end:
                raise TemplateSyntaxError("Unterminated string in expression", lineno)
            tokens.append(source_text[i:j+1])
            i = j + 1
            continue

        # Integer
        if c.isdigit() or (c == '-' and i + 1 < n and source_text[i+1].isdigit()):
            j = i
            if c == '-':
                j += 1
            while j < n and source_text[j].isdigit():
                j += 1
            tokens.append(source_text[i:j])
            i = j
            continue

        # Word/Name
        if c.isalpha() or c == '_':
            j = i
            while j < n and (source_text[j].isalnum() or source_text[j] == '_'):
                j += 1
            val = source_text[i:j]
            tokens.append(val)
            i = j
            continue

        raise TemplateSyntaxError(f"Unexpected character '{c}' in expression", lineno)

    return tokens

def parse_expression(source_text: str, lineno: int) -> ExprNode:
    """
    Parse a value expression string like "user.name|upper"
    """
    tokens = _tokenize_inner(source_text, lineno)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        if pos < len(tokens):
            tok = tokens[pos]
            pos += 1
            return tok
        return None

    def check_reserved(name):
        if name in ('and', 'or', 'not', 'in'):
            raise TemplateSyntaxError(f"Reserved word '{name}' used as name", lineno)

    def parse_atom():
        tok = peek()
        if tok is None:
            raise TemplateSyntaxError("Unexpected end of expression", lineno)

        # String
        if tok and tok[0] in "\"'":
            advance()
            return LiteralNode(tok[1:-1])

        # Integer
        if tok and (tok[0].isdigit() or (tok[0] == '-' and len(tok) > 1 and tok[1].isdigit())):
            advance()
            return LiteralNode(int(tok))

        # Name
        if tok and (tok[0].isalpha() or tok[0] == '_'):
            if tok in ('and', 'or', 'not', 'in'):
                raise TemplateSyntaxError(f"Reserved word '{tok}' used as name", lineno)
            advance()
            root = tok
            segments = []
            while peek() == '.':
                advance() # .
                seg_tok = peek()
                if seg_tok is None:
                    raise TemplateSyntaxError("Unexpected end of expression after dot", lineno)
                advance()

                if seg_tok and seg_tok[0].isdigit():
                    # Segment must be non-negative integer
                    if not seg_tok.isdigit(): # Handle negative? Spec says non-negative.
                         raise TemplateSyntaxError(f"Invalid segment '{seg_tok}'", lineno)
                    segments.append(seg_tok)
                elif seg_tok and (seg_tok[0].isalpha() or seg_tok[0] == '_'):
                    check_reserved(seg_tok)
                    segments.append(seg_tok)
                else:
                    raise TemplateSyntaxError(f"Invalid segment '{seg_tok}'", lineno)
            return VarPathNode(root, segments)

        raise TemplateSyntaxError(f"Unexpected token in expression: {tok}", lineno)

    def parse_filters(node):
        while peek() == '|':
            advance() # |
            name_tok = peek()
            if name_tok is None or not (name_tok[0].isalpha() or name_tok[0] == '_'):
                raise TemplateSyntaxError("Invalid filter name", lineno)
            advance()
            fname = name_tok

            args = []
            if peek() == ':':
                advance() # :
                arg_tok = peek()
                if arg_tok is None:
                    raise TemplateSyntaxError("Missing argument for filter", lineno)
                advance()

                if arg_tok[0] in "\"'":
                    args.append(LiteralNode(arg_tok[1:-1]))
                elif arg_tok[0].isdigit() or (arg_tok[0] == '-' and len(arg_tok) > 1 and arg_tok[1].isdigit()):
                    args.append(LiteralNode(int(arg_tok)))
                else:
                    raise TemplateSyntaxError(f"Invalid filter argument: {arg_tok}", lineno)

            node = FilterNode(node, fname, args)
        return node

    node = parse_atom()
    node = parse_filters(node)

    if pos != len(tokens):
        raise TemplateSyntaxError("Unexpected tokens at end of expression", lineno)

    return node

def parse_condition(source_text: str, lineno: int) -> ConditionNode:
    """
    Parse a condition string.
    Precedence: or, and, not, comparison.
    """
    tokens = _tokenize_inner(source_text, lineno)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        if pos < len(tokens):
            tok = tokens[pos]
            pos += 1
            return tok
        return None

    def parse_value_expr():
        # Reuse logic from parse_expression but inline or call it?
        # Calling parse_expression is cleaner but it takes string. 
        # We have tokens. Let's refactor to share parser or duplicate small logic.
        # Duplicating atom+filter parsing for tokens is safe.

        # Atom
        tok = peek()
        if tok is None:
            raise TemplateSyntaxError("Unexpected end of condition", lineno)

        node = None
        if tok[0] in "\"'":
            advance()
            node = LiteralNode(tok[1:-1])
        elif tok[0].isdigit() or (tok[0] == '-' and len(tok) > 1 and tok[1].isdigit()):
            advance()
            node = LiteralNode(int(tok))
        elif tok[0].isalpha() or tok[0] == '_':
            if tok in ('and', 'or', 'not', 'in'):
                raise TemplateSyntaxError(f"Reserved word '{tok}' in condition", lineno)
            advance()
            root = tok
            segments = []
            while peek() == '.':
                advance() # .
                seg_tok = peek()
                if seg_tok is None:
                    raise TemplateSyntaxError("Unexpected end after dot", lineno)
                advance()

                if seg_tok[0].isdigit():
                    if not seg_tok.isdigit():
                         raise TemplateSyntaxError(f"Invalid segment '{seg_tok}'", lineno)
                    segments.append(seg_tok)
                elif seg_tok[0].isalpha() or seg_tok[0] == '_':
                    if seg_tok in ('and', 'or', 'not', 'in'):
                        raise TemplateSyntaxError(f"Reserved word in path", lineno)
                    segments.append(seg_tok)
                else:
                    raise TemplateSyntaxError(f"Invalid segment", lineno)
            node = VarPathNode(root, segments)
        else:
            raise TemplateSyntaxError(f"Unexpected token in condition: {tok}", lineno)

        # Filters
        while peek() == '|':
            advance()
            fname = peek()
            if fname is None or not (fname[0].isalpha() or fname[0] == '_'):
                raise TemplateSyntaxError("Invalid filter name", lineno)
            advance()

            args = []
            if peek() == ':':
                advance()
                arg = peek()
                if arg is None:
                    raise TemplateSyntaxError("Missing argument", lineno)
                advance()
                if arg[0] in "\"'":
                    args.append(LiteralNode(arg[1:-1]))
                elif arg[0].isdigit() or (arg[0] == '-' and len(arg) > 1 and arg[1].isdigit()):
                    args.append(LiteralNode(int(arg)))
                else:
                    raise TemplateSyntaxError("Invalid argument", lineno)
            node = FilterNode(node, fname, args)

        return node

    def parse_comp_expr():
        left = parse_value_expr()
        op = peek()
        if op in ("==", "!=", "<", "<=", ">", ">="):
            advance()
            right = parse_value_expr()
            return ConditionNode('comp', left, op, right)
        return ConditionNode('val', left)

    def parse_not_expr():
        if peek() == 'not':
            advance()
            inner = parse_not_expr()
            return ConditionNode('not', inner)
        return parse_comp_expr()

    def parse_and_expr():
        left = parse_not_expr()
        while peek() == 'and':
            advance()
            right = parse_not_expr()
            left = ConditionNode('and', left, right)
        return left

    def parse_or_expr():
        left = parse_and_expr()
        while peek() == 'or':
            advance()
            right = parse_and_expr()
            left = ConditionNode('or', left, right)
        return left

    cond = parse_or_expr()
    if pos != len(tokens):
        raise TemplateSyntaxError("Extra tokens in condition", lineno)

    return cond

def parse_block_content(content: str, lineno: int):
    """
    Parse the content of a block tag {% ... %}
    """
    parts = content.split(maxsplit=1)
    if not parts:
        raise TemplateSyntaxError("Empty block tag", lineno)

    keyword = parts[0]
    rest = parts[1].strip() if len(parts) > 1 else ""

    if keyword in ('endfor', 'endif', 'else'):
        if rest:
            raise TemplateSyntaxError(f"Unexpected content after '{keyword}'", lineno)
        return (keyword,)

    if keyword == 'elif':
        if not rest:
            raise TemplateSyntaxError("Missing condition for elif", lineno)
        cond = parse_condition(rest, lineno)
        return ('elif', cond)

    if keyword == 'for':
        # Find ' in ' outside strings
        in_idx = -1
        in_str = False
        quote_char = None
        for i in range(len(rest)):
            c = rest[i]
            if in_str:
                if c == quote_char:
                    in_str = False
            else:
                if c in ("\"", "'"):
                    in_str = True
                    quote_char = c
                elif c == ' ' and i > 0 and i < len(rest) - 1:
                    # Check if we have " in " starting at i-1
                    if rest.startswith(" in ", i - 1):
                        # Ensure boundaries (not part of larger word)
                        # i-1 is space before 'in'
                        # i+2 is space after 'in'? 
                        # "in " is 3 chars.
                        # We found " in " at i-1.
                        # Check if next char is space or start of expr
                        # Actually " in " is enough.
                        in_idx = i - 1
                        break

        if in_idx == -1:
             raise TemplateSyntaxError("Malformed for loop: missing 'in'", lineno)

        target_name = rest[:in_idx].strip()
        expr_str = rest[in_idx+4:].strip() # Skip " in "

        if not target_name:
            raise TemplateSyntaxError("Missing loop variable name", lineno)
        if not (target_name[0].isalpha() or target_name[0] == '_'):
            raise TemplateSyntaxError("Invalid loop variable name", lineno)
        if target_name in ('and', 'or', 'not', 'in', 'for', 'if', 'else', 'elif', 'endfor', 'endif'):
            raise TemplateSyntaxError(f"Cannot use reserved word '{target_name}' as loop variable", lineno)

        expr = parse_expression(expr_str, lineno)
        return ('for', target_name, expr)

    if keyword == 'if':
        if not rest:
            raise TemplateSyntaxError("Missing condition for if", lineno)
        cond = parse_condition(rest, lineno)
        return ('if', cond)

    raise TemplateSyntaxError(f"Unknown statement '{keyword}'", lineno)

def parse(source: str) -> list:
    """
    Parse the template source into a list of AST nodes.
    """
    tokens = tokenize(source)

    stack = []
    top_level_nodes = []

    def add_node(node):
        if stack:
            current = stack[-1]
            if current['type'] == 'if':
                if current['state'] == 'if_body':
                    current['current_body'].append(node)
                elif current['state'] == 'else_body':
                    current['else_body'].append(node)
            elif current['type'] == 'for':
                if current['state'] == 'body':
                    current['body'].append(node)
                elif current['state'] == 'else_body':
                    current['else_body'].append(node)
        else:
            top_level_nodes.append(node)

    for tok in tokens:
        if tok.kind == "text":
            if tok.value:
                add_node(TextNode(tok.value))

        elif tok.kind == "var":
            expr = parse_expression(tok.value, tok.lineno)
            add_node(VarNode(expr, tok.lineno))

        elif tok.kind == "block":
            block_info = parse_block_content(tok.value, tok.lineno)
            cmd = block_info[0]

            if cmd == 'if':
                cond = block_info[1]
                stack.append({
                    'type': 'if',
                    'lineno': tok.lineno,
                    'branches': [],
                    'else_body': None,
                    'state': 'if_body',
                    'current_body': [],
                    'current_cond': cond
                })

            elif cmd == 'elif':
                if not stack or stack[-1]['type'] != 'if':
                    raise TemplateSyntaxError("elif without if", tok.lineno)
                current = stack[-1]
                if current['state'] == 'else_body':
                    raise TemplateSyntaxError("elif after else", tok.lineno)

                # Close current branch
                current['branches'].append((current['current_cond'], current['current_body']))

                # Start new branch
                current['current_body'] = []
                current['current_cond'] = block_info[1]
                current['state'] = 'if_body'

            elif cmd == 'else':
                if not stack:
                    raise TemplateSyntaxError("else without block", tok.lineno)
                current = stack[-1]
                if current['state'] == 'else_body':
                    raise TemplateSyntaxError("double else", tok.lineno)

                if current['type'] == 'if':
                    current['branches'].append((current['current_cond'], current['current_body']))
                    current['else_body'] = []
                    current['state'] = 'else_body'
                elif current['type'] == 'for':
                    current['else_body'] = []
                    current['state'] = 'else_body'
                else:
                    raise TemplateSyntaxError("else outside block", tok.lineno)

            elif cmd == 'endif':
                if not stack or stack[-1]['type'] != 'if':
                    raise TemplateSyntaxError("endif without if", tok.lineno)
                current = stack.pop()
                if current['state'] == 'if_body':
                    current['branches'].append((current['current_cond'], current['current_body']))

                node = IfNode(current['branches'], current['else_body'], current['lineno'])
                add_node(node)

            elif cmd == 'endfor':
                if not stack or stack[-1]['type'] != 'for':
                    raise TemplateSyntaxError("endfor without for", tok.lineno)
                current = stack.pop()
                node = ForNode(current['target'], current['expr'], current['body'], current['else_body'], current['lineno'])
                add_node(node)

            elif cmd == 'for':
                target, expr = block_info[1], block_info[2]
                stack.append({
                    'type': 'for',
                    'lineno': tok.lineno,
                    'target': target,
                    'expr': expr,
                    'body': [],
                    'else_body': None,
                    'state': 'body'
                })

            else:
                raise TemplateSyntaxError(f"Unknown block command {cmd}", tok.lineno)

    if stack:
        current = stack[-1]
        if current['type'] == 'if':
            raise TemplateSyntaxError("Unclosed if block", current['lineno'])
        elif current['type'] == 'for':
            raise TemplateSyntaxError("Unclosed for block", current['lineno'])

    return top_level_nodes
