import collections.abc
from .lexer import TemplateRenderError
from .parser import (
    parse, TextNode, VarNode, IfNode, ForNode,
    ExprNode, LiteralNode, VarPathNode, FilterNode,
    ConditionNode
)

def _get_value(path_node: VarPathNode, context: dict, lineno: int):
    """Resolve a variable path against the context."""
    # First get the root name
    if path_node.root in context:
        val = context[path_node.root]
    else:
        val = None

    for segment in path_node.segments:
        if val is None:
            break

        # Mapping
        if isinstance(val, collections.abc.Mapping):
            if segment in val:
                val = val[segment]
            else:
                val = None
        # List/Tuple
        elif isinstance(val, (list, tuple)):
            # segment is string in node, try to convert to int
            try:
                idx = int(segment)
                if idx < 0 or idx >= len(val):
                    val = None
                else:
                    val = val[idx]
            except ValueError:
                val = None
        # Object attribute
        else:
            # Name segment, not starting with _
            if segment and segment[0].isalpha() or segment and segment[0] == '_':
                 if segment.startswith('_'):
                     val = None
                 else:
                     val = getattr(val, segment, None)
            else:
                val = None

    return val

def _eval_expr(expr: ExprNode, context: dict, lineno: int):
    """Evaluate a value expression."""
    if isinstance(expr, LiteralNode):
        return expr.value

    if isinstance(expr, VarPathNode):
        return _get_value(expr, context, lineno)

    if isinstance(expr, FilterNode):
        val = _eval_expr(expr.target, context, lineno)
        return _apply_filter(val, expr.name, expr.args, lineno)

    raise TemplateRenderError(f"Unknown expression type {type(expr)}", lineno)

def _apply_filter(val, name, args, lineno):
    """Apply a filter to a value."""
    def get_arg_str():
        if not args:
            raise TemplateRenderError(f"Filter '{name}' requires a string argument", lineno)
        arg = args[0].value
        if not isinstance(arg, str):
            raise TemplateRenderError(f"Filter '{name}' requires a string argument", lineno)
        return arg

    def get_arg_int():
        if not args:
            raise TemplateRenderError(f"Filter '{name}' requires an integer argument", lineno)
        arg = args[0].value
        if not isinstance(arg, int):
            raise TemplateRenderError(f"Filter '{name}' requires an integer argument", lineno)
        return arg

    if name == 'upper':
        if args: raise TemplateRenderError(f"Filter '{name}' takes no arguments", lineno)
        return _output_text(val).upper()

    if name == 'lower':
        if args: raise TemplateRenderError(f"Filter '{name}' takes no arguments", lineno)
        return _output_text(val).lower()

    if name == 'trim':
        if args: raise TemplateRenderError(f"Filter '{name}' takes no arguments", lineno)
        return _output_text(val).strip()

    if name == 'length':
        if args: raise TemplateRenderError(f"Filter '{name}' takes no arguments", lineno)
        if val is None:
            return 0
        try:
            return len(val)
        except TypeError:
            raise TemplateRenderError(f"Filter 'length' cannot handle {type(val)}", lineno)

    if name == 'first':
        if args: raise TemplateRenderError(f"Filter '{name}' takes no arguments", lineno)
        if val is None or _is_empty(val):
            return None
        if isinstance(val, str):
            return val[0]
        if isinstance(val, (list, tuple)):
            return val[0]
        try:
            return next(iter(val))
        except StopIteration:
            return None
        except TypeError:
            raise TemplateRenderError(f"Filter 'first' cannot handle {type(val)}", lineno)

    if name == 'last':
        if args: raise TemplateRenderError(f"Filter '{name}' takes no arguments", lineno)
        if val is None or _is_empty(val):
            return None
        if isinstance(val, str):
            return val[-1]
        if isinstance(val, (list, tuple)):
            return val[-1]
        # For other iterables
        try:
            last = None
            found = False
            for item in val:
                last = item
                found = True
            return last if found else None
        except TypeError:
            raise TemplateRenderError(f"Filter 'last' cannot handle {type(val)}", lineno)

    if name == 'reverse':
        if args: raise TemplateRenderError(f"Filter '{name}' takes no arguments", lineno)
        if val is None:
            return None
        if isinstance(val, str):
            return val[::-1]
        try:
            # For lists, tuples, etc.
            # Spec: "list of any other value's items in reverse order"
            return list(reversed(val))
        except TypeError:
            raise TemplateRenderError(f"Filter 'reverse' cannot handle {type(val)}", lineno)

    if name == 'join':
        sep = get_arg_str()
        if val is None:
            return ""
        try:
            items = []
            for item in val:
                items.append(_output_text(item))
            return sep.join(items)
        except TypeError:
            raise TemplateRenderError(f"Filter 'join' cannot handle {type(val)}", lineno)

    if name == 'default':
        if not args:
            raise TemplateRenderError(f"Filter 'default' requires an argument", lineno)
        arg_val = args[0].value
        if val is None or (isinstance(val, str) and val == ""):
            return arg_val
        return val

    if name == 'truncate':
        n = get_arg_int()
        if n < 0:
            raise TemplateRenderError(f"Filter 'truncate' argument must be >= 0", lineno)
        text = _output_text(val)
        if len(text) > n:
            return text[:n] + "..."
        return text

    if name == 'items':
        if args: raise TemplateRenderError(f"Filter '{name}' takes no arguments", lineno)
        if val is None:
            return []
        if isinstance(val, collections.abc.Mapping):
            return list(val.items())
        raise TemplateRenderError(f"Filter 'items' requires a mapping", lineno)

    raise TemplateRenderError(f"Unknown filter '{name}'", lineno)

def _output_text(val) -> str:
    """Convert value to output text."""
    if val is None:
        return ""
    return str(val)

def _is_empty(val) -> bool:
    if val is None:
        return True
    if isinstance(val, str):
        return len(val) == 0
    if isinstance(val, (list, tuple)):
        return len(val) == 0
    # Assume non-empty for others unless we know better
    return False

def _compare(left, right, op, lineno):
    """Compare two values with the given operator."""
    try:
        if op == '==':
            return left == right
        elif op == '!=':
            return left != right
        elif op == '<':
            return left < right
        elif op == '<=':
            return left <= right
        elif op == '>':
            return left > right
        elif op == '>=':
            return left >= right
    except TypeError:
        raise TemplateRenderError("Cannot compare values of incompatible types", lineno)
    raise TemplateRenderError(f"Unknown operator {op}", lineno)

def _eval_condition(cond: ConditionNode, context: dict, lineno: int) -> bool:
    """Evaluate a condition node."""
    if cond.type == 'val':
        val = _eval_expr(cond.args[0], context, lineno)
        return bool(val)

    if cond.type == 'comp':
        left = _eval_expr(cond.args[0], context, lineno)
        op = cond.args[1]
        right = _eval_expr(cond.args[2], context, lineno)
        return _compare(left, right, op, lineno)

    if cond.type == 'not':
        inner = _eval_condition(cond.args[0], context, lineno)
        return not inner

    if cond.type == 'and':
        left = _eval_condition(cond.args[0], context, lineno)
        if not left:
            return False
        return _eval_condition(cond.args[1], context, lineno)

    if cond.type == 'or':
        left = _eval_condition(cond.args[0], context, lineno)
        if left:
            return True
        return _eval_condition(cond.args[1], context, lineno)

    raise TemplateRenderError(f"Unknown condition type {cond.type}", lineno)

