import re


class ErrorValue(str):
    """A string subclass that represents error values like #ERROR! and #CYCLE!."""
    __slots__ = ()


class FormulaError(ValueError):
    """Raised when a formula fails to parse or evaluate."""
    pass


# --- Syntax tree node types ---

class Number:
    """A numeric literal. int if no dot, float otherwise."""
    __slots__ = ("value",)

    def __init__(self, value):
        self.value = value


class Ref:
    """A cell reference like A1, B2, etc."""
    __slots__ = ("name",)

    def __init__(self, name):
        self.name = name


class Unary:
    """A unary + or - applied to an expression."""
    __slots__ = ("op", "operand")

    def __init__(self, op, operand):
        self.op = op
        self.operand = operand


class Binary:
    """A binary arithmetic operation."""
    __slots__ = ("op", "left", "right")

    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right


# --- Lexer ---

# Regex for individual tokens without leading whitespace consumption in the match itself for cleaner position checking
# We match whitespace separately or use a scanner approach.
# Using a simpler regex that doesn't consume leading whitespace in the token group start calculation issue.
_TOKEN_RE = re.compile(r'\s*([+-/*()]|[A-Za-z]+[0-9]+|[0-9]+\.?[0-9]*)')


def _tokenize(text):
    """Tokenize formula text into a list of (kind, value) tuples.
    Returns None if there are leftover characters or invalid syntax."""
    tokens = []
    pos = 0
    n = len(text)
    while pos < n:
        # Skip whitespace
        while pos < n and text[pos].isspace():
            pos += 1
        if pos >= n:
            break

        # Find match starting at pos
        m = _TOKEN_RE.match(text, pos)
        if not m:
            return None

        # The regex matches whitespace before the token. 
        # m.end() is the end of the entire match (including leading whitespace if any, though we already skipped some)
        # Actually, since we skipped whitespace in the loop, pos points to a non-whitespace char.
        # _TOKEN_RE starts with \s*, so it matches 0 whitespace then the token.
        # So m.start(1) should be pos if there was no extra whitespace matched by \s* that we didn't skip?
        # Wait, we skipped whitespace. So pos is at non-space.
        # The regex \s* will match 0 spaces. Then match the token.
        # So m.start(1) == pos is expected.

        if m.start(1) != pos:
             # This can happen if \s* matched some whitespace that we thought we skipped but didn't?
             # No, we skipped all whitespace. So \s* matches empty string.
             # If m.start(1) != pos, it means the regex engine matched something weird?
             # Or if the regex allowed skipping whitespace and we didn't?
             # Let's just check if the match is valid.
             pass

        # Check if the matched token starts exactly at pos (after our manual whitespace skip)
        # Since we manually skipped whitespace, pos is at non-whitespace.
        # The regex \s* matches 0 chars. Then it must match a token starting at pos.
        # So m.start(1) must equal pos.
        if m.start(1) != pos:
            return None

        tok_str = m.group(1)
        pos = m.end()

        if tok_str in '+-/*()':
            tokens.append((tok_str, tok_str))
        elif tok_str[0].isalpha():
            tokens.append(('ref', tok_str))
        elif tok_str[0].isdigit():
            tokens.append(('num', tok_str))
        else:
            return None

    return tokens


# --- Parser ---

_CELL_RE = re.compile(r'^([A-Za-z]+)([0-9]+)$')


def _parse_ref(name):
    """Parse a reference string, returning upper-case name or raising FormulaError."""
    m = _CELL_RE.match(name)
    if not m:
        raise FormulaError(f"invalid reference: {name}")
    letters, digits = m.group(1), m.group(2)
    if len(letters) > 1:
        raise FormulaError(f"invalid reference: {name}")
    if len(digits) > 1 and digits[0] == '0':
        raise FormulaError(f"invalid reference: {name}")
    row = int(digits)
    if row < 1 or row > 999:
        raise FormulaError(f"invalid reference: {name}")
    return name.upper()


class _Parser:
    """Recursive-descent parser for spreadsheet formulas."""

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos][0]
        return None

    def consume(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind):
        if self.peek() != kind:
            raise FormulaError(f"expected '{kind}'")
        return self.consume()

    def parse(self):
        if not self.tokens:
            raise FormulaError("empty formula")
        result = self.parse_expr()
        if self.pos < len(self.tokens):
            raise FormulaError("unexpected token")
        return result

    def parse_expr(self):
        node = self.parse_term()
        while self.peek() in ('+', '-'):
            op = self.consume()[0]
            right = self.parse_term()
            node = Binary(op, node, right)
        return node

    def parse_term(self):
        node = self.parse_unary()
        while self.peek() in ('*', '/'):
            op = self.consume()[0]
            right = self.parse_unary()
            node = Binary(op, node, right)
        return node

    def parse_unary(self):
        kind = self.peek()
        if kind in ('+', '-'):
            self.consume()
            operand = self.parse_unary()
            return Unary(kind, operand)
        if kind == 'num':
            tok = self.consume()
            s = tok[1]
            if '.' in s:
                return Number(float(s))
            return Number(int(s))
        if kind == 'ref':
            tok = self.consume()
            name = _parse_ref(tok[1])
            return Ref(name)
        if kind == '(':
            self.consume()
            node = self.parse_expr()
            self.expect(')')
            return node
        if kind is None:
            raise FormulaError("unexpected end of formula")
        raise FormulaError(f"unexpected token: {kind}")


def parse_formula(source: str):
    """Parse the text after '=' into a syntax tree. Raises FormulaError on bad input."""
    tokens = _tokenize(source)
    if tokens is None:
        raise FormulaError("invalid character in formula")
    parser = _Parser(tokens)
    return parser.parse()


def references(tree) -> set:
    """Return the set of upper-case cell names referenced by the formula tree."""
    result = set()
    _collect_refs(tree, result)
    return result


def _collect_refs(node, acc):
    if isinstance(node, Ref):
        acc.add(node.name)
    elif isinstance(node, Number):
        pass
    elif isinstance(node, Unary):
        _collect_refs(node.operand, acc)
    elif isinstance(node, Binary):
        _collect_refs(node.left, acc)
        _collect_refs(node.right, acc)


# --- Evaluation ---

ERROR = ErrorValue("#ERROR!")
CYCLE = ErrorValue("#CYCLE!")

_ARITH_OPS = {
    '+': lambda a, b: a + b,
    '-': lambda a, b: a - b,
    '*': lambda a, b: a * b,
    '/': lambda a, b: a / b,
}


def evaluate(tree, lookup):
    """Evaluate a formula tree. lookup(name) returns the cell's current value."""
    if isinstance(tree, Number):
        return tree.value
    if isinstance(tree, Ref):
        val = lookup(tree.name)
        if val is None:
            return 0
        return val
    if isinstance(tree, Unary):
        return _eval_unary(tree, lookup)
    if isinstance(tree, Binary):
        return _eval_binary(tree, lookup)
    raise FormulaError("unknown node type")


def _eval_unary(node, lookup):
    val = evaluate(node.operand, lookup)
    if isinstance(val, ErrorValue):
        return val
    if isinstance(val, str):
        return ERROR
    # Numeric
    if node.op == '+':
        return val
    # node.op == '-'
    if isinstance(val, int):
        return -val
    return -val


def _eval_binary(node, lookup):
    left = evaluate(node.left, lookup)
    right = evaluate(node.right, lookup)

    # Error propagation: left error wins if both are errors
    if isinstance(left, ErrorValue):
        return left
    if isinstance(right, ErrorValue):
        return right

    # Text operands → #ERROR!
    if isinstance(left, str) or isinstance(right, str):
        return ERROR

    # Division by zero
    if node.op == '/' and right == 0:
        return ERROR

    try:
        result = _ARITH_OPS[node.op](left, right)
    except (ZeroDivisionError, TypeError, ValueError):
        return ERROR

    # / always gives float
    if node.op == '/':
        return float(result)
    return result
