class DependencyGraph:
    """Tracks dependency relationships between spreadsheet cells.

    All cell names passed to and returned from this class are upper-case.
    """

    def __init__(self):
        # cell -> set of cells it depends on (precedents)
        self._precedents = {}
        # cell -> set of cells that depend on it (dependents)
        self._dependents = {}

    def set_dependencies(self, cell, precedents):
        """Replace cell's precedents with the given iterable.

        Updates the reverse dependents mapping accordingly.
        Passing an empty iterable removes all dependencies for cell.
        """
        old = self._precedents.get(cell, set())
        new = set(precedents)

        # Remove cell from the dependents of cells no longer referenced
        for p in old - new:
            deps = self._dependents.get(p)
            if deps is not None:
                deps.discard(cell)
                if not deps:
                    del self._dependents[p]

        # Add cell to the dependents of newly referenced cells
        for p in new - old:
            self._dependents.setdefault(p, set()).add(cell)

        if new:
            self._precedents[cell] = new
        else:
            self._precedents.pop(cell, None)

    def precedents(self, cell):
        """Return the set of cells that cell's formula refers to (direct)."""
        return set(self._precedents.get(cell, set()))

    def dependents(self, cell):
        """Return the set of cells whose formulas refer to cell (direct)."""
        return set(self._dependents.get(cell, set()))

    def all_dependents(self, cell):
        """Return all cells that refer to cell directly or transitively.

        Includes cell itself only if it lies on a cycle reachable from it.
        """
        # BFS/DFS through the dependents graph
        # We start by adding direct dependents to the stack.
        # If we encounter `cell` again, it's on a cycle.

        visited = set()
        stack = []

        # Add direct dependents to stack
        for d in self._dependents.get(cell, ()):
            if d == cell:
                # Self-loop
                visited.add(cell)
            else:
                stack.append(d)

        # If cell itself is a direct dependent, we already handled it.
        # We need to find all cells reachable from `cell` via the dependents edge.
        # Note: `all_dependents` means cells that depend on `cell` (directly or indirectly).
        # In graph terms, if A depends on B, edge is B -> A in dependents graph.
        # So we traverse edges from `cell`.

        # Re-evaluating traversal:
        # We want {D | cell ->* D} in dependents graph.
        # And if cell ->* cell, include cell.

        stack = list(self._dependents.get(cell, ()))
        visited = set()
        found_cell = False

        while stack:
            current = stack.pop()
            if current == cell:
                found_cell = True
                continue
            if current in visited:
                continue
            visited.add(current)
            for d in self._dependents.get(current, ()):
                if d not in visited:
                    stack.append(d)

        if found_cell:
            visited.add(cell)

        return visited

    def cycle_cells(self):
        """Return the set of all cells that lie on a dependency cycle.

        A cell is on a cycle if following its precedents (and transitively
        their precedents) can lead back to the cell itself.
        """
        result = set()
        # A cell is on a cycle if it is reachable from itself in the precedents graph.
        # Precedents graph: A -> B if A depends on B.
        # Cycle: A depends on B, B depends on A.
        # Path in precedents graph from A to A.

        for cell in self._precedents:
            # BFS from cell's precedents
            stack = list(self._precedents.get(cell, ()))
            visited = set()
            while stack:
                current = stack.pop()
                if current == cell:
                    result.add(cell)
                    break
                if current in visited:
                    continue
                visited.add(current)
                for p in self._precedents.get(current, ()):
                    if p not in visited:
                        stack.append(p)
        return result
