_CELL_NAME_RE = re.compile(r'^([A-Z])([1-9][0-9]*)$')
_NUMERIC_RE = re.compile(r'^-?\d+(\.\d+)?$')


def _row_major_key(name):
    row = int(name[1:])
    col = name[0]
    return (row, col)


def _sort_row_major(names):
    return sorted(names, key=_row_major_key)


class _CellData:
    """Internal record for each non-empty cell."""

    def __init__(self, input_raw, is_formula, value, tree, precedents):
        self.input_raw = input_raw
        self.is_formula = is_formula
        self.value = value
        self.tree = tree
        self.precedents = precedents


class Sheet:
    def __init__(self):
        self._cells = {}           # name -> _CellData
        self._graph = DependencyGraph()
        self.evaluations = 0

    def set(self, name, raw):
        if not isinstance(raw, str):
            raise TypeError("raw must be a string")

        upper = self._validate_name(name)

        # Parse or validate the input before modifying any state
        is_formula = False
        parsed_tree = None
        new_precedents = set()
        new_value = None
        new_input = raw

        if raw == '':
            pass # Empty handled below
        elif raw.startswith('='):
            try:
                parsed_tree = parse_formula(raw[1:])
            except FormulaError:
                raise
            is_formula = True
            new_precedents = references(parsed_tree)
            # Validate that all referenced cells exist within sheet bounds
            # parse_formula already ensures they are valid formats, 
            # but check against sheet bounds just in case? 
            # parse_formula checks bounds (A-Z, 1-999).
            # So they are valid cell names.
        else:
            stripped = raw.strip()
            if _NUMERIC_RE.match(stripped):
                if '.' in stripped:
                    new_value = float(stripped)
                else:
                    new_value = int(stripped)
            else:
                new_value = raw

        # Determine cells to recalculate based on current state (before update for "affected"?)
        # Spec: "returns the cells whose value may have changed... the cell itself plus every cell in its all_dependents"
        # "set evaluates each formula cell in its returned list..."

        # 1. Update Graph and Cell Store
        if raw == '':
            if upper in self._cells:
                self._graph.set_dependencies(upper, set())
                del self._cells[upper]
            # If not in cells, nothing to do for graph/store
        else:
            # If existing, clear old deps
            if upper in self._cells:
                self._graph.set_dependencies(upper, set())

            # Store new cell data
            # Note: For formula cells, value is initially None/old? 
            # We will set it during evaluation.
            self._cells[upper] = _CellData(
                new_input, is_formula, new_value, parsed_tree, new_precedents
            )
            if new_precedents:
                self._graph.set_dependencies(upper, new_precedents)

        # 2. Determine Affected Cells
        # Affected = {upper} U all_dependents(upper) in the *new* graph state.
        affected = {upper} | self._graph.all_dependents(upper)

        # 3. Identify Cells to Evaluate
        # Filter: must be in self._cells, must be formula, must not be on a cycle.
        cycle_set = self._graph.cycle_cells()

        # Set cycle values immediately
        for c in cycle_set:
            if c in self._cells:
                self._cells[c].value = CYCLE

        to_eval = []
        for c in affected:
            if c in self._cells:
                cell_data = self._cells[c]
                if cell_data.is_formula and c not in cycle_set:
                    to_eval.append(c)
            # If c is not in _cells (e.g. emptied), it's not a formula, so skip.
            # Note: cycle_set cells are already set to CYCLE above.

        if not to_eval:
            return _sort_row_major(affected)

        to_eval_set = set(to_eval)

        # Topological Sort
        # Edge: Precedent -> Dependent
        # We need to evaluate Precedent before Dependent.

        in_degree = {c: 0 for c in to_eval_set}
        adj = {c: [] for c in to_eval_set} # Adjacency list: Precedent -> [Dependents]

        for c in to_eval_set:
            cell_data = self._cells[c]
            for pre in cell_data.precedents:
                if pre in to_eval_set:
                    in_degree[c] += 1
                    adj[pre].append(c)

        queue = [c for c in to_eval_set if in_degree[c] == 0]
        ordered = []

        while queue:
            # Pop arbitrary (e.g. index 0)
            u = queue.pop(0)
            ordered.append(u)
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        # Evaluate
        # Define lookup function for this evaluation pass
        def lookup(ref_name):
            if ref_name in self._cells:
                return self._cells[ref_name].value
            return None

        for c in ordered:
            cell_data = self._cells[c]
            try:
                val = evaluate(cell_data.tree, lookup)
            except Exception:
                val = ERROR

            cell_data.value = val
            self.evaluations += 1

        return _sort_row_major(affected)

    def get(self, name):
        upper = self._validate_name(name)
        if upper in self._cells:
            return self._cells[upper].value
        return None

    def raw(self, name):
        upper = self._validate_name(name)
        if upper in self._cells:
            return self._cells[upper].input_raw
        return ''

    def cells(self):
        return _sort_row_major(self._cells.keys())

    @staticmethod
    def _validate_name(name):
        if not isinstance(name, str):
            raise ValueError(f"invalid cell name: {name!r}")
        upper = name.upper()
        m = _CELL_NAME_RE.match(upper)
        if not m:
            raise ValueError(f"invalid cell name: {name!r}")
        return upper
